mapper.insert:
INSERT INTO trade_order (
    order_no, request_id, buyer_id, seller_id, product_id, quantity,
    unit_price, total_amount, trade_time, trade_place, remark, status, confirm_deadline
) VALUES (
    #{orderNo}, #{requestId}, #{buyerId}, #{sellerId}, #{productId}, #{quantity},
    #{unitPrice}, #{totalAmount}, #{tradeTime}, #{tradePlace}, #{remark}, #{status}, #{confirmDeadline}
)

INSERT INTO trade_order_log (
    order_id, from_status, to_status, operator_type, operator_id, reason
) VALUES (
    #{orderId}, #{fromStatus}, #{toStatus}, #{operatorType}, #{operatorId}, #{reason}
)

mapper.update:
UPDATE trade_order
SET status = 1
WHERE id = #{id}
  AND seller_id = #{sellerId}
  AND status = 0

UPDATE trade_order
SET status = 2,
    finished_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND buyer_id = #{buyerId}
  AND status = 1

